describe('File Upload - Folder Organisation', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should upload files and organise them into folders', () => {
    // Intercept the file upload API
    cy.intercept('POST', '/api/files/upload').as('uploadFiles');

    // Click the folder dropdown
    cy.get('[data-testid="folder-dropdown"]').click();

    // Select the 'Documents' folder
    cy.get('[data-testid="folder-option-documents"]').click();

    // Click the file input button
    cy.get('[data-testid="upload-file-button"]').click();

    // Upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample-document.pdf', { force: true });

    // Wait for the upload API call
    cy.wait('@uploadFiles');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'File uploaded successfully');

    // Verify file appears in the correct folder
    cy.get('[data-testid="file-list"]').should('contain', 'sample-document.pdf');
    cy.get('[data-testid="folder-name"]').should('contain', 'Documents');

    // Verify file has folder icon
    cy.get('[data-testid="file-item"]').should('have.class', 'in-folder');
  });

  it('should handle multiple file uploads and create new folders if needed', () => {
    // Intercept the file upload API
    cy.intercept('POST', '/api/files/upload').as('uploadFiles');

    // Click the folder dropdown
    cy.get('[data-testid="folder-dropdown"]').click();

    // Select the 'Images' folder
    cy.get('[data-testid="folder-option-images"]').click();

    // Upload multiple files
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample-image1.jpg cypress/fixtures/sample-image2.jpg', { force: true });

    // Wait for the upload API call
    cy.wait('@uploadFiles');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Files uploaded successfully');

    // Verify all files appear in the Images folder
    cy.get('[data-testid="file-list"]').should('contain', 'sample-image1.jpg');
    cy.get('[data-testid="file-list"]').should('contain', 'sample-image2.jpg');
    cy.get('[data-testid="folder-name"]').should('contain', 'Images');

    // Verify folder icon is present
    cy.get('[data-testid="folder-icon"]').should('be.visible');
  });
});
